package io.github.matosoe.controlehoras.ui.goals;
import android.os.Bundle; import android.view.*; import android.widget.*; import androidx.annotation.Nullable; import androidx.fragment.app.Fragment; import androidx.lifecycle.ViewModelProvider; import androidx.recyclerview.widget.LinearLayoutManager; import java.time.format.DateTimeFormatter; import io.github.matosoe.controlehoras.R; import io.github.matosoe.controlehoras.domain.service.DurationFormatter;
public final class GoalsFragment extends Fragment { public GoalsFragment(){super(R.layout.fragment_goals);} @Override public void onViewCreated(View v,@Nullable Bundle b){GoalsViewModel m=new ViewModelProvider(this).get(GoalsViewModel.class);Spinner p=v.findViewById(R.id.goals_period);p.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,new String[]{"Dia","Semana","Personalizado"}));GoalsAdapter a=new GoalsAdapter(row->edit(m,row));((androidx.recyclerview.widget.RecyclerView)v.findViewById(R.id.goals_list)).setLayoutManager(new LinearLayoutManager(requireContext()));((androidx.recyclerview.widget.RecyclerView)v.findViewById(R.id.goals_list)).setAdapter(a);p.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> x){}public void onItemSelected(AdapterView<?> x,View y,int pos,long id){if(pos!=m.mode())m.setMode(pos);}});v.findViewById(R.id.goals_custom).setOnClickListener(x->{java.time.LocalDate d=java.time.LocalDate.now();m.setCustom(d.minusDays(6),d);p.setSelection(GoalsViewModel.CUSTOM);});TextView range=v.findViewById(R.id.goals_range),total=v.findViewById(R.id.goals_total),warning=v.findViewById(R.id.goals_warning);m.state().observe(getViewLifecycleOwner(),s->{if(s.loading)return;a.submit(s.rows);range.setText(s.start.format(DateTimeFormatter.ofPattern("dd/MM/yyyy"))+" – "+s.end.minusDays(1).format(DateTimeFormatter.ofPattern("dd/MM/yyyy")));DurationFormatter f=new DurationFormatter();total.setText("Registrado: "+f.hhMm(s.registered)+" · Não classificado: "+f.hhMm(s.unclassified));warning.setText(s.targetTotal==10000?"":"Soma das metas: "+(s.targetTotal/100.0)+"%");});} private void edit(GoalsViewModel m,GoalRow row){View v=LayoutInflater.from(requireContext()).inflate(R.layout.dialog_edit_goal,null);EditText value=v.findViewById(R.id.goal_target_input);value.setText(String.valueOf(row.category.targetBasisPoints/100.0));Spinner type=v.findViewById(R.id.goal_type_input);String[] options={"MINIMO","MAXIMO"};type.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,options));type.setSelection("MAXIMO".equals(row.category.goalType)?1:0);new androidx.appcompat.app.AlertDialog.Builder(requireContext()).setTitle(row.category.name).setView(v).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.save,(d,w)->{try{int bp=(int)Math.round(Double.parseDouble(value.getText().toString().replace(',','.'))*100);io.github.matosoe.controlehoras.data.local.entity.CategoryEntity c=new io.github.matosoe.controlehoras.data.local.entity.CategoryEntity(row.category.id,row.category.name,row.category.colorArgb,row.category.displayOrder,options[type.getSelectedItemPosition()],bp,row.category.active);m.update(c,new io.github.matosoe.controlehoras.data.repository.RepositoryCallback<Integer>(){public void onSuccess(Integer i){m.setMode(m.mode());}public void onError(Throwable t){}});}catch(Exception e){Toast.makeText(requireContext(),"Percentual inválido",Toast.LENGTH_LONG).show();}}).show();}}
